/* The 27 defined bytes in 0x80..0x9f, sorted by codepoint. */
static const struct {
    uint16_t uni;
    uint8_t byte;
} k_specials[] = {
    { 0x0152, 0x8c }, { 0x0153, 0x9c }, { 0x0160, 0x8a }, { 0x0161, 0x9a },
    { 0x0178, 0x9f }, { 0x017d, 0x8e }, { 0x017e, 0x9e }, { 0x0192, 0x83 },
    { 0x02c6, 0x88 }, { 0x02dc, 0x98 }, { 0x2013, 0x96 }, { 0x2014, 0x97 },
    { 0x2018, 0x91 }, { 0x2019, 0x92 }, { 0x201a, 0x82 }, { 0x201c, 0x93 },
    { 0x201d, 0x94 }, { 0x201e, 0x84 }, { 0x2020, 0x86 }, { 0x2021, 0x87 },
    { 0x2022, 0x95 }, { 0x2026, 0x85 }, { 0x2030, 0x89 }, { 0x2039, 0x8b },
    { 0x203a, 0x9b }, { 0x20ac, 0x80 }, { 0x2122, 0x99 },
};

AnemStatus anem_cp1252_to_uni(uint8_t byte, uint16_t *uni)
{
    if (uni == NULL) {
        return ANEM_BADARG;
    }
    *uni = k_cp1252_to_uni[byte];
    if (*uni == 0xffffu) {          /* undefined in the codepage */
        return ANEM_FORMAT;
    }
    return ANEM_OK;
}

AnemStatus anem_uni_to_cp1252(uint16_t uni, uint8_t *byte)
{
    if (byte == NULL) {
        return ANEM_BADARG;
    }
    if (uni < 0x80u || (uni >= 0xa0u && uni <= 0xffu)) {
        *byte = (uint8_t)uni;       /* CP1252 is identity outside 0x80..0x9f */
        return ANEM_OK;
    }
    for (unsigned i = 0; i < sizeof k_specials / sizeof k_specials[0]; i++) {
        if (k_specials[i].uni == uni) {     /* linear: 27 entries, cold path */
            *byte = k_specials[i].byte;
            return ANEM_OK;
        }
    }
    return ANEM_FORMAT;
}

AnemStatus anem_utf8_encode(uint32_t codepoint, uint8_t out[4], size_t *written)
{
    if (out == NULL || written == NULL) {
        return ANEM_BADARG;
    }
    if (codepoint > 0x10ffffu || (codepoint >= 0xd800u && codepoint <= 0xdfffu)) {
        return ANEM_FORMAT;         /* out of range, or a surrogate half */
    }
    if (codepoint < 0x80u) {
        out[0] = (uint8_t)codepoint;
        *written = 1;
    } else if (codepoint < 0x800u) {
        out[0] = (uint8_t)(0xc0u | (codepoint >> 6));
        out[1] = (uint8_t)(0x80u | (codepoint & 0x3fu));
        *written = 2;
    } else if (codepoint < 0x10000u) {
        out[0] = (uint8_t)(0xe0u | (codepoint >> 12));
        out[1] = (uint8_t)(0x80u | ((codepoint >> 6) & 0x3fu));
        out[2] = (uint8_t)(0x80u | (codepoint & 0x3fu));
        *written = 3;
    } else {
        out[0] = (uint8_t)(0xf0u | (codepoint >> 18));
        out[1] = (uint8_t)(0x80u | ((codepoint >> 12) & 0x3fu));
        out[2] = (uint8_t)(0x80u | ((codepoint >> 6) & 0x3fu));
        out[3] = (uint8_t)(0x80u | (codepoint & 0x3fu));
        *written = 4;
    }
    return ANEM_OK;
}

AnemStatus anem_utf8_decode(const uint8_t *text, size_t len,
                            uint32_t *codepoint, size_t *consumed)
{
    uint32_t v;
    size_t need;

    if (text == NULL || codepoint == NULL || consumed == NULL) {
        return ANEM_BADARG;
    }
    if (len == 0) {
        return ANEM_FORMAT;         /* no sequence to read */
    }
    v = text[0];
    if (v < 0x80u) {
        *codepoint = v;
        *consumed = 1;
        return ANEM_OK;
    }
    if (v < 0xc0u) {
        return ANEM_FORMAT;         /* stray continuation byte */
    }
    if (v < 0xe0u) {
        need = 2;
        v &= 0x1fu;
    } else if (v < 0xf0u) {
        need = 3;
        v &= 0x0fu;
    } else if (v < 0xf8u) {
        need = 4;
        v &= 0x07u;
    } else {
        return ANEM_FORMAT;         /* 5- and 6-byte forms are not UTF-8 */
    }
    if (len < need) {
        return ANEM_FORMAT;         /* truncated */
    }
    for (size_t i = 1; i < need; i++) {      /* i rises by 1 each pass */
        if ((text[i] & 0xc0u) != 0x80u) {
            return ANEM_FORMAT;
        }
        v = (v << 6) | (text[i] & 0x3fu);
    }
#ifndef ANEM_NLS_NEGATIVE
    if ((need == 2 && v < 0x80u) || (need == 3 && v < 0x800u)
        || (need == 4 && v < 0x10000u)) {
        return ANEM_FORMAT;         /* overlong */
    }
#endif
    if (v > 0x10ffffu || (v >= 0xd800u && v <= 0xdfffu)) {
        return ANEM_FORMAT;         /* out of range, or a surrogate half */
    }
    *codepoint = v;
    *consumed = need;
    return ANEM_OK;
}
